-- 评分显示用附魔（无属性，只显示「附魔：评分 N」）
SET NAMES utf8mb4;
SET @hid = (SELECT IFNULL(MAX(Id),0) FROM hotfixes.hotfix_data);
DELETE FROM hotfixes.hotfix_data WHERE TableHash=3764045193 AND RecordId BETWEEN 210001 AND 211000;
DELETE FROM hotfixes.spell_item_enchantment_locale WHERE ID BETWEEN 210001 AND 211000;
DELETE FROM hotfixes.spell_item_enchantment WHERE ID BETWEEN 210001 AND 211000;
SELECT COUNT(*) AS score_enchants FROM hotfixes.spell_item_enchantment WHERE ID BETWEEN 210001 AND 211000;
